#pragma once
#include <cmath>
namespace rsm { struct Vector3 { float x=0,y=0,z=0; constexpr Vector3()=default; constexpr Vector3(float X,float Y,float Z):x(X),y(Y),z(Z){} constexpr Vector3 operator+(const Vector3&o)const{return{x+o.x,y+o.y,z+o.z};} constexpr Vector3 operator-(const Vector3&o)const{return{x-o.x,y-o.y,z-o.z};} constexpr Vector3 operator*(float s)const{return{x*s,y*s,z*s};} constexpr float Dot(const Vector3&o)const{return x*o.x+y*o.y+z*o.z;} float Length()const{return std::sqrt(Dot(*this));} }; }